/**
 * Sign-in.
 *
 * Next 16: `searchParams` is a Promise and must be awaited (AGENTS.md #1). The
 * `PageProps<'/login'>` helper is generated by `next typegen`, so the prop type is
 * not hand-written.
 */

import Link from 'next/link';
import { redirect } from 'next/navigation';

import { getSession } from '@/lib/auth/session';

import { MagicLinkForm } from './MagicLinkForm';

export const metadata = {
  title: 'Sign in · Lantage',
  description: 'Verified-professional access to the Lantage image-intelligence workbench.',
};

export default async function LoginPage(props: PageProps<'/login'>) {
  const params = await props.searchParams;

  // The proxy also redirects an authenticated user away from here. Repeated
  // server-side because the proxy is not the authorization boundary — a matcher
  // change must not turn this page into a way to re-authenticate over a live
  // session.
  const session = await getSession();
  if (session) redirect(safeNext(params.next) ?? '/');

  return (
    <div className="glass-card blur-in p-7">
      <div className="mb-6 space-y-2">
        <p className="eyebrow-mono">LANTAGE · VERIFIED ACCESS</p>
        <h1 className="text-2xl">Sign in</h1>
        <p className="text-sm text-fg-secondary">
          Every search is attributed to a verified professional account and recorded in an
          immutable audit log. There is no anonymous access.
        </p>
      </div>

      <MagicLinkForm next={safeNext(params.next)} />

      <p className="mt-6 border-t border-border pt-4 text-xs text-fg-tertiary">
        Access requires a verified licence or an organisation agreement. Need an account?{' '}
        <Link href="/" className="text-fg-secondary underline underline-offset-2 hover:text-fg">
          Contact us
        </Link>
        .
      </p>
    </div>
  );
}

/**
 * A `?next=` that came in over the wire is attacker-controlled. Only a
 * same-origin, single-slash path is allowed through — `//evil.com` and
 * `https://evil.com` are both rejected, and so is `/login` itself, which would
 * loop.
 */
function safeNext(value: string | string[] | undefined): string | undefined {
  const raw = Array.isArray(value) ? value[0] : value;
  if (!raw) return undefined;
  if (!raw.startsWith('/')) return undefined;
  if (raw.startsWith('//')) return undefined;
  if (raw.startsWith('/login')) return undefined;
  return raw;
}
